import { cookies } from "next/headers";
import { randomUUID } from "crypto";
import { prisma } from "@/infrastructure/db/prisma";

const COOKIE_NAME = "ai_insider_uid";

// v1 has no accounts/login. Each browser gets a UUID in a cookie, and we
// create a matching User row lazily. This is enough to persist per-user
// progress without building a signup flow — see architecture plan's
// "What we're NOT doing."
export async function getOrCreateUserId(): Promise<string> {
  const cookieStore = await cookies();
  const existing = cookieStore.get(COOKIE_NAME)?.value;

  if (existing) {
    const user = await prisma.user.findUnique({ where: { id: existing } });
    if (user) return user.id;
  }

  const newUser = await prisma.user.create({ data: {} });
  cookieStore.set(COOKIE_NAME, newUser.id, {
    httpOnly: true,
    sameSite: "lax",
    maxAge: 60 * 60 * 24 * 365,
  });
  return newUser.id;
}
